function lines(s){return s.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);}
function time(s){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(s)) throw Error('Use HH:MM in 24-hour time'); const [h,m]=s.split(':').map(Number); return h*60+m;}

function run(d){
const seen=new Set(), source=lines(d.items), unique=source.filter(x=>{const key=x; if(seen.has(key)) return false; seen.add(key); return true;}); return {unique:unique.length,removed:source.length-unique.length,items:unique.join(', ')};
}
"}

